# Create the users blueprint
users_bp = Blueprint('users', __name__)

@users_bp.route('/', methods=['GET'])
def list_users():
    """List all users"""
    return jsonify({'users': [
        {'id': 1, 'name': 'Alice', 'email': 'alice@example.com'},
        {'id': 2, 'name': 'Bob', 'email': 'bob@example.com'},
        {'id': 3, 'name': 'Charlie', 'email': 'charlie@example.com'}
    ]})

@users_bp.route('/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get a specific user by ID"""
    return jsonify({'id': user_id, 'name': f'User {user_id}', 'email': f'user{user_id}@example.com'})

@users_bp.route('/', methods=['POST'])
def create_user():
    """Create a new user"""
    return jsonify({'message': 'User created', 'id': 4}), 201

@users_bp.route('/<int:user_id>', methods=['PUT'])
def update_user(user_id):
    """Update a user"""
    return jsonify({'message': f'User {user_id} updated', 'id': user_id})

@users_bp.route('/<int:user_id>', methods=['DELETE'])
def delete_user(user_id):
    """Delete a user"""
    return jsonify({'message': f'User {user_id} deleted'}), 204

# Create the main Flask application
app = Flask(__name__)

# Register the users blueprint with URL prefix
app.register_blueprint(users_bp, url_prefix='/users')

@app.route('/')
def home():
