    return jsonify({'message': 'Welcome to the Flask API', 'endpoints': {
        'users': '/users',
        'user': '/users/<id>'
    }})

@app.route('/health', methods=['GET'])
def health():
    """Health check endpoint"""
    return jsonify({'status': 'healthy'})

if __name__ == '__main__':
